import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI


def _coerce_json(text: str) -> Dict[str, Any]:
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        start = text.find("{")
        end = text.rfind("}")
        if start != -1 and end != -1 and end > start:
            return json.loads(text[start : end + 1])
        raise


def validate_structured_document(
    document_text: str,
    required_fields: List[str],
    min_confidence: float = 0.8,
    model: str = "gpt-4.1-mini",
) -> Dict[str, Any]:
    """
    Uses OpenAI structured outputs to extract required fields and confidence scores
    from an unstructured document, then validates presence and confidence thresholds.

    Returns:
        {
            "valid": bool,
            "missing_fields": [...],
            "low_confidence_fields": [{"field": ..., "confidence": ...}, ...],
            "extracted": {...},
            "raw": {...}
        }
    """
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    schema = {
        "type": "object",
        "properties": {
            "fields": {
                "type": "object",
                "additionalProperties": {
                    "type": "object",
                    "properties": {
                        "value": {"type": ["string", "number", "boolean", "null"]},
                        "confidence": {"type": "number"},
                    },
                    "required": ["value", "confidence"],
                    "additionalProperties": False,
                },
            }
        },
        "required": ["fields"],
        "additionalProperties": False,
    }

    prompt = {
        "role": "user",
        "content": (
            "Extract the required fields from the document.\n"
            "For each required field, return an object with:\n"
            "- value: the extracted value or null if missing\n"
            "- confidence: a number from 0 to 1 representing extraction confidence\n\n"
            f"Required fields: {required_fields}\n\n"
            "Document:\n"
            f"{document_text}"
        ),
    }

    response = client.responses.create(
        model=model,
        input=[prompt],
        response_format={
            "type": "json_schema",
            "json_schema": {
                "name": "document_extraction",
                "schema": schema,
                "strict": True,
            },
        },
    )

    raw_output = response.output_text
    extracted = _coerce_json(raw_output)

    fields = extracted.get("fields", {})
    missing_fields: List[str] = []
    low_confidence_fields: List[Dict[str, Any]] = []

    normalized_extracted: Dict[str, Any] = {}

    for field in required_fields:
        field_data = fields.get(field)
        if not isinstance(field_data, dict):
            missing_fields.append(field)
            normalized_extracted[field] = {"value": None, "confidence": 0.0}
            continue

        value = field_data.get("value")
        confidence = field_data.get("confidence")

        if value in (None, "", []):
            missing_fields.append(field)

        try:
            confidence_value = float(confidence)
        except (TypeError, ValueError):
            confidence_value = 0.0

        if confidence_value < min_confidence:
            low_confidence_fields.append(
                {"field": field, "confidence": confidence_value}
            )

        normalized_extracted[field] = {
            "value": value,
            "confidence": confidence_value,
        }

    valid = not missing_fields and not low_confidence_fields

    return {
        "valid": valid,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "extracted": normalized_extracted,
        "raw": extracted,
    }
